const norm = s => (s || '').replace(/\s+/g, ' ').trim();
const box = n => n.absoluteBoundingBox;
const near = (a, b, tol) => Math.abs(a - b) <= tol;

function iou(a, b) {
  const x1 = Math.max(a[0], b[0]), y1 = Math.max(a[1], b[1]);
  const x2 = Math.min(a[0] + a[2], b[0] + b[2]), y2 = Math.min(a[1] + a[3], b[1] + b[3]);
  const inter = Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
  const uni = a[2] * a[3] + b[2] * b[3] - inter;
  return uni > 0 ? inter / uni : 0;
}

function depth(node, root) {
  let d = 0;
  while (node && node !== root) { node = node.parent; d++; }
  return d;
}

function findScreens(page, report) {
  const byLabel = new Map(DATA.map(f => [f.label, f]));
  const labelNodes = new Map();
  for (const t of page.findAllWithCriteria({ types: ['TEXT'] })) {
    const k = norm(t.characters);
    if (byLabel.has(k) && !labelNodes.has(k) && box(t)) labelNodes.set(k, t);
  }
  const sized = page.findAll(n => {
    const b = box(n);
    return b && ((near(b.width, 1440, 2) && near(b.height, 900, 2)) || (near(b.width, 390, 2) && near(b.height, 844, 2)));
  });
  const screens = new Map();
  for (const f of DATA) {
    const t = labelNodes.get(f.label);
    if (!t) { report.push('Не знайдено підпис: ' + f.label); continue; }
    const lb = box(t);
    let best = null, bestScore = Infinity;
    for (const n of sized) {
      const b = box(n);
      if (!near(b.width, f.w, 2) || !near(b.height, f.h, 2)) continue;
      const dy = b.y - (lb.y + lb.height);
      if (!near(b.x, lb.x, 8) || dy < -2 || dy > 60) continue;
      const score = depth(n, page);
      if (score < bestScore) { bestScore = score; best = n; }
    }
    if (best) screens.set(f.label, best); else report.push('Не знайдено екран під підписом: ' + f.label);
  }
  return screens;
}

function placeScreens(page, screens) {
  const before = page.children.slice();
  let bottom = 0;
  for (const n of before) { const b = box(n); if (b) bottom = Math.max(bottom, b.y + b.height); }
  const rows = new Map();
  for (const f of DATA) {
    const key = f.label.split(' / ')[1];
    if (!rows.has(key)) rows.set(key, []);
    rows.get(key).push(f);
  }
  const frames = new Map();
  let y = bottom + 800;
  for (const list of rows.values()) {
    let x = 0, rowH = 0;
    for (const f of list) {
      const node = screens.get(f.label);
      if (!node) continue;
      let frame;
      if (node.type === 'FRAME') {
        page.appendChild(node);
        frame = node;
        if (frame.layoutMode && frame.layoutMode !== 'NONE') {
          frame.primaryAxisSizingMode = 'FIXED';
          frame.counterAxisSizingMode = 'FIXED';
        }
        frame.resize(f.w, f.h);
      } else {
        frame = figma.createFrame();
        frame.resize(f.w, f.h);
        frame.fills = [];
        page.appendChild(frame);
        frame.appendChild(node);
        node.x = 0;
        node.y = 0;
      }
      frame.x = x;
      frame.y = y;
      frame.name = f.label;
      frame.clipsContent = true;
      frames.set(f.label, frame);
      x += f.w + 80;
      rowH = Math.max(rowH, f.h);
    }
    y += rowH + 240;
  }
  for (const n of before) {
    if (!n.removed && n.parent === page && ![...frames.values()].includes(n)) {
      n.name = 'Залишок імпорту (можна видалити)';
      n.visible = false;
    }
  }
  return frames;
}

const cache = new Map();
function nodesOf(screen) {
  if (!cache.has(screen.id)) {
    const sb = box(screen);
    const list = screen.findAll(n => !!box(n)).map(n => {
      const b = box(n);
      return { n, rel: [b.x - sb.x, b.y - sb.y, b.width, b.height], d: depth(n, screen) };
    });
    const texts = screen.findAllWithCriteria({ types: ['TEXT'] });
    cache.set(screen.id, { list, texts });
  }
  return cache.get(screen.id);
}

function pickNode(screen, link) {
  const { list, texts } = nodesOf(screen);
  let best = null, bestDepth = Infinity, bestIou = 0;
  for (const it of list) {
    const v = iou(it.rel, link.box);
    if (v >= 0.85) {
      if (it.d < bestDepth) { best = it.n; bestDepth = it.d; bestIou = v; }
    } else if (bestDepth === Infinity && v > bestIou && v >= 0.6) {
      bestIou = v;
      best = it.n;
    }
  }
  if (best) return best;
  const [lx, ly, lw, lh] = link.box;
  let inner = null, innerArea = 0;
  for (const it of list) {
    const [x, y, w, h] = it.rel;
    if (x >= lx - 3 && y >= ly - 3 && x + w <= lx + lw + 3 && y + h <= ly + lh + 3 && w * h > innerArea && w * h >= 0.15 * lw * lh) {
      inner = it.n;
      innerArea = w * h;
    }
  }
  if (inner) return inner;
  if (link.text) {
    const same = texts.filter(t => norm(t.characters) === link.text);
    const t = same[link.nth] || same[0];
    if (t) return t;
  }
  for (const a of link.alt || []) {
    const t = texts.find(x => norm(x.characters).includes(norm(a)));
    if (t) return t;
  }
  return null;
}

async function linkScreens(frames, report) {
  let made = 0, skipped = 0;
  for (const f of DATA) {
    const screen = frames.get(f.label);
    if (!screen) continue;
    for (const link of f.links) {
      const dest = frames.get(link.target);
      if (!dest) { skipped++; continue; }
      const node = pickNode(screen, link);
      if (!node) {
        report.push(`${f.label}: «${link.text || (link.alt || [])[0] || 'елемент без тексту'}» → ${link.target}`);
        skipped++;
        continue;
      }
      if (node.reactions.some(r => r.trigger && r.trigger.type === 'ON_CLICK')) continue;
      const reaction = {
        trigger: { type: 'ON_CLICK' },
        actions: [{ type: 'NODE', destinationId: dest.id, navigation: 'NAVIGATE', transition: null }]
      };
      await node.setReactionsAsync([...node.reactions, reaction]);
      made++;
    }
  }
  return { made, skipped };
}

async function writeReport(page, frames, result, report) {
  try {
    await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
    const t = figma.createText();
    t.fontName = { family: 'Inter', style: 'Regular' };
    t.fontSize = 24;
    const lines = [
      'Звіт плагіна «КіноГраф: зв\'язки»',
      `Екранів знайдено: ${frames.size} з ${DATA.length}`,
      `Зв'язків створено: ${result.made}, не вдалося: ${result.skipped}`,
      '',
      ...report.slice(0, 80)
    ];
    if (report.length > 80) lines.push(`… і ще ${report.length - 80}`);
    t.characters = lines.join('\n');
    const first = [...frames.values()][0];
    t.x = first ? first.x : 0;
    t.y = first ? first.y - 200 - t.height : 0;
    t.name = 'Звіт плагіна';
    page.appendChild(t);
  } catch (e) {
    console.log(report.join('\n'));
  }
}

async function main() {
  const page = figma.currentPage;
  const report = [];
  const screens = findScreens(page, report);
  if (screens.size === 0) {
    figma.closePlugin('Не знайдено жодного екрана. Відкрийте сторінку з імпортованою дошкою.');
    return;
  }
  const frames = placeScreens(page, screens);
  const result = await linkScreens(frames, report);
  const starts = [];
  const desk = frames.get('Десктоп / 4.1 Каталог / звичайний');
  const phone = frames.get('Телефон / 4.1 Каталог / звичайний');
  if (desk) starts.push({ nodeId: desk.id, name: 'КіноГраф — десктоп' });
  if (phone) starts.push({ nodeId: phone.id, name: 'КіноГраф — телефон' });
  page.flowStartingPoints = starts;
  await writeReport(page, frames, result, report);
  figma.viewport.scrollAndZoomIntoView([...frames.values()]);
  figma.closePlugin(`Готово: ${frames.size} екранів, ${result.made} зв'язків, не вдалося ${result.skipped}`);
}

main().catch(e => figma.closePlugin('Помилка: ' + e.message));
